<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../includes/online.php';
require_once __DIR__.'/ordering-fixture.php';
require_once __DIR__.'/delivery-fixture.php';
$checks=0;
function delivery_check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);$checks++;echo "PASS: $label\n";}
function delivery_reject(callable $fn,int $status,string $label):void{try{$fn();}catch(OrderError $error){delivery_check($error->status===$status,$label);return;}throw new RuntimeException('Unexpected acceptance: '.$label);}
$db=quvo_db();$target=$db->query("SELECT DB_NAME() name,CONVERT(nvarchar(128),SERVERPROPERTY('MachineName')) machine")->fetch();
if($target['name']!=='QuvoCafeDB'||strcasecmp($target['machine'],getenv('COMPUTERNAME')?:'')!==0)throw new RuntimeException('Local test database required.');
$db->beginTransaction();
try{
    $identity=ordering_test_open($db);$actor=$identity['actor'];$tag=bin2hex(random_bytes(5));$settings=delivery_test_settings($db);
    delivery_check($settings['available']&&$settings['phoneLink']==='tel:09778010771'&&$settings['facebook']==='https://www.facebook.com/QuvoCafe','saved cafe address, Facebook and phone become pickup settings');
    $initialVersion=$settings['version'];
    $unsafe=delivery_test_settings($db,['social'=>'https://example.invalid/facebook.com']);delivery_check($unsafe['facebook']===''&&$unsafe['available'],'non-Facebook social URLs are omitted while a valid phone remains available');
    $settings=delivery_test_settings($db);delivery_check($settings['version']===$initialVersion,'settings version depends on pickup details rather than unrelated editor revisions');
    $account=online_register($db,['name'=>'Lalamove test','email'=>'delivery-'.$tag.'@example.invalid','contact'=>'09123456789','address'=>'Customer destination stays in profile','password'=>'Rollback-only-123']);$customer=(int)$account['customer_account_id'];
    $other=online_register($db,['name'=>'Other test','email'=>'delivery-other-'.$tag.'@example.invalid','contact'=>'09123456789','address'=>'Other address','password'=>'Rollback-only-123']);
    $q=$db->prepare("INSERT dbo.menu_items(item_name,category,price,is_available) OUTPUT INSERTED.menu_item_id VALUES(?,'cold-coffee',100,1)");$q->execute(['Delivery '.$tag]);$menu=(int)$q->fetchColumn();$q->closeCursor();
    $png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aV5kAAAAASUVORK5CYII=');
    payment_qr_save($db,(int)$actor['staff_id'],'GCash',payment_image($png));$version=payment_qr_methods($db)['GCash']['version'];
    $base=['fulfillment'=>'delivery','contact'=>'09123456789','expected_total'=>'100.00','payment_method'=>'GCash','payment_qr_version'=>$version,'receipt_image'=>'data:image/png;base64,'.base64_encode($png),'items'=>[['itemId'=>$menu,'quantity'=>1]]]+delivery_test_payload($db,$png);
    $submit=fn(array $changes=[])=>online_submit($db,$customer,array_replace($base,['submission_key'=>ordering_test_uuid()],$changes));
    $count=(int)$db->query('SELECT COUNT(*) FROM dbo.orders')->fetchColumn();
    delivery_reject(fn()=>$submit(['booking_image'=>null]),422,'delivery requires a booking screenshot');
    delivery_reject(fn()=>$submit(['receipt_image'=>null]),422,'delivery requires a separate payment receipt');
    delivery_reject(fn()=>$submit(['booking_image'=>'data:text/html;base64,WA==']),422,'booking upload rejects non-image content');
    delivery_reject(fn()=>$submit(['booking_image'=>'data:image/png;base64,'.base64_encode(str_repeat('x',2097153))]),422,'booking image larger than two MB is rejected');
    delivery_reject(fn()=>$submit(['delivery_config_version'=>str_repeat('0',64)]),409,'stale pickup details require checkout review');
    delivery_reject(fn()=>$submit(['delivery_flow'=>'legacy','address'=>'Customer address']),409,'new staff-coordinated delivery requests require the new flow');
    delivery_reject(fn()=>$submit(['fulfillment'=>'pickup']),422,'pickup cannot silently retain a courier booking');
    delivery_check((int)$db->query('SELECT COUNT(*) FROM dbo.orders')->fetchColumn()===$count,'invalid proof/config requests create no partial orders');
    delivery_test_settings($db,['address'=>'']);delivery_reject(fn()=>$submit(),422,'delivery is unavailable without a configured cafe pickup address');$settings=delivery_test_settings($db);
    $request=$base+['submission_key'=>ordering_test_uuid(),'address'=>'Forged customer address must not become pickup'];
    $saved=online_submit($db,$customer,$request);$order=$saved['order'];$id=(int)$order['order_id'];
    delivery_check($order['delivery_provider']==='lalamove'&&$order['fulfillment_type']==='delivery','order records customer-booked Lalamove delivery');
    delivery_check($order['pickup_address_snapshot']==='Quvo test pickup address'&&$order['address_snapshot']===null,'server snapshots cafe pickup address and ignores customer/forged address');
    delivery_check($order['cafe_phone_snapshot']==='09778010771'&&$order['cafe_facebook_snapshot']==='https://www.facebook.com/QuvoCafe','cafe contact snapshots are saved with the order');
    delivery_check($order['contact_snapshot']==='09123456789'&&$order['recipient_name']==='Lalamove test','customer identity/contact are retained separately from cafe pickup details');
    delivery_check((int)$order['has_payment_receipt']===1&&(int)$order['has_delivery_booking']===1,'both proofs are present on the accepted order');
    delivery_check($order['total_amount']==='100.00'&&$order['payment_status']==='unpaid','courier fee is separate and screenshot does not confirm payment');
    delivery_check(hex2bin(delivery_booking_image($db,$id,$customer)['image_hex'])===$png,'customer retrieves exact booking image bytes');
    delivery_check(hex2bin(delivery_booking_image($db,$id)['image_hex'])===$png,'protected staff endpoint can retrieve booking image bytes');
    $db->prepare("UPDATE dbo.order_fulfillments SET delivery_provider=NULL,address_snapshot='Legacy metadata fixture' WHERE order_id=?")->execute([$id]);
    delivery_check(hex2bin(delivery_booking_image($db,$id,$customer)['image_hex'])===$png,'saved booking evidence remains readable if provider metadata is missing');
    delivery_reject(fn()=>delivery_booking_image($db,$id,(int)$other['customer_account_id']),404,'missing provider metadata still cannot expose another customer booking');
    $db->prepare("UPDATE dbo.order_fulfillments SET delivery_provider='lalamove',address_snapshot=NULL WHERE order_id=?")->execute([$id]);
    delivery_reject(fn()=>delivery_booking_image($db,$id,(int)$other['customer_account_id']),404,'another customer cannot read booking proof');
    delivery_check(!isset($order['image_bytes'],$order['image_hex'],$order['booking_image']),'order JSON does not expose full booking image content');
    $day=(new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')))->format('Y-m-d');
    $records=payment_receipt_records($db,$day,'all',0,(string)$order['order_number']);delivery_check(count($records['uploads'])===1&&(int)$records['uploads'][0]['has_delivery_booking']===1&&$records['uploads'][0]['fulfillment_type']==='delivery','Receipts customer uploads identifies delivery and the second proof');
    delivery_check(online_submit($db,$customer,$request)['replayed'],'identical retry recovers the accepted order');
    delivery_reject(fn()=>online_submit($db,$customer,array_replace($request,['booking_image'=>'data:image/png;base64,'.base64_encode($png.'different')])),409,'changed booking cannot reuse an accepted submission key');
    delivery_test_settings($db,['address'=>'Updated cafe pickup address']);
    delivery_check(online_submit($db,$customer,$request)['replayed'],'accepted retry still works after cafe address changes');
    delivery_check(online_order($db,$customer,$id)['pickup_address_snapshot']==='Quvo test pickup address','saved pickup address remains historical after settings edits');
    delivery_reject(fn()=>$submit(),409,'a new order cannot use the old pickup address version');
    $large=str_pad($png,2097152,"\0");$current=delivery_test_payload($db,$large);
    $largeOrder=$submit($current+['receipt_image'=>'data:image/png;base64,'.base64_encode($large)]);
    delivery_check(strlen(hex2bin(delivery_booking_image($db,(int)$largeOrder['order']['order_id'],$customer)['image_hex']))===2097152,'maximum-size two-MB booking and payment images are accepted together');
    $pickup=$base;$pickup['fulfillment']='pickup';unset($pickup['delivery_flow'],$pickup['delivery_config_version'],$pickup['booking_image']);$pickup['submission_key']=ordering_test_uuid();
    $pickupOrder=online_submit($db,$customer,$pickup)['order'];delivery_check($pickupOrder['delivery_provider']===null&&(int)$pickupOrder['has_delivery_booking']===0,'standard pickup needs only the payment receipt');
    delivery_reject(fn()=>delivery_booking_image($db,(int)$pickupOrder['order_id'],$customer),404,'pickup orders have no courier image to expose');
    $legacy=$pickup;$legacy['fulfillment']='delivery';$legacy['address']='Original historical destination';$legacy['submission_key']=ordering_test_uuid();
    $legacyHash=hash('sha256',json_encode([orders_lines($legacy['items']),10000,'delivery','GCash',$legacy['address'],$legacy['contact'],[$version,hash('sha256',$png)]],JSON_THROW_ON_ERROR));
    $db->prepare('UPDATE dbo.orders SET submission_key=?,submission_hash=CONVERT(binary(32),?,2) WHERE order_id=?')->execute([$legacy['submission_key'],$legacyHash,$pickupOrder['order_id']]);
    $db->prepare("UPDATE dbo.order_fulfillments SET fulfillment_type='delivery',address_snapshot=? WHERE order_id=?")->execute([$legacy['address'],$pickupOrder['order_id']]);
    $legacyRecovered=online_submit($db,$customer,$legacy);
    delivery_check($legacyRecovered['replayed']&&$legacyRecovered['order']['address_snapshot']===$legacy['address']&&$legacyRecovered['order']['delivery_provider']===null,'an accepted legacy delivery still replays with its original destination');
    delivery_reject(fn()=>online_submit($db,$customer,array_replace($legacy,['submission_key'=>ordering_test_uuid()])),409,'legacy delivery may replay but cannot create another new staff-coordinated request');
    orders_cancel($db,$actor,$id,'Delivery test cancellation');
    $records=payment_receipt_records($db,$day,'cancelled',0,(string)$order['order_number']);delivery_check(count($records['uploads'])===1&&$records['uploads'][0]['date_basis']==='cancellation'&&(int)$records['uploads'][0]['has_delivery_booking']===1,'cancelled receipt history keeps both proofs and cancellation date');
    delivery_check(hex2bin(delivery_booking_image($db,$id,$customer)['image_hex'])===$png,'cancelled order retains booking evidence');
    delivery_reject(fn()=>online_orders($db,$customer,0,'invalid'),422,'unknown order scopes are rejected');
    delivery_check(online_orders($db,(int)$other['customer_account_id'],0,'active')['orders']===[],'current order lists stay scoped to their customer');
    for($index=0;$index<21;$index++){
        $closed=$pickup;$closed['submission_key']=ordering_test_uuid();
        $closedId=(int)online_submit($db,$customer,$closed)['order']['order_id'];
        orders_cancel($db,$actor,$closedId,'Rollback-only history fixture');
    }
    $history=online_orders($db,$customer);$active=online_orders($db,$customer,0,'active');
    delivery_check(!in_array($largeOrder['order']['order_id'],array_column($history['orders'],'order_id'),true),'newer closed history can push an unfinished order outside the newest history page');
    delivery_check(in_array($largeOrder['order']['order_id'],array_column($active['orders'],'order_id'),true),'current orders still include older unfinished orders');
    delivery_check(count(array_filter($active['orders'],fn($row)=>!in_array($row['order_status'],['received','preparing','ready'],true)))===0,'current orders exclude closed and cancelled history');
    delivery_check(count($history['orders'])===20&&$history['next_offset']===20,'history keeps its original pagination');
    $db->exec(file_get_contents(__DIR__.'/../database/23_customer_booked_delivery.sql'));delivery_check((int)online_order($db,$customer,$id)['has_delivery_booking']===1,'migration can run again without losing uploaded proof');
    echo "Completed $checks customer-booked delivery checks; all fixtures roll back.\n";
}finally{if($db->inTransaction())$db->rollBack();}
